/**
 * Recipes: the homepage block (components/sections/Recipes), /recipes and /recipes/[slug].
 * Copy, quantities and steps approved (all six recipes). Each engraving is generated by
 * tools/engravings/recipes.mjs (public/engravings/recipe-{slug}.svg, and .png for JSON-LD).
 * No health claims here: taste and method only.
 */
export type SaltHandle = 'herbal-black-salt' | 'natural-lake-salt';

export interface Recipe {
  slug: string;
  name: string;
  /** a second name, shown small under the title */
  aka?: string;
  /** what the engraving shows (its alt text) */
  art: string;
  description: string;
  serves: number;
  minutes: number;
  salts: SaltHandle[];
  ingredients: string[];
  steps: string[];
}

export const SALT_NAMES: Record<SaltHandle, string> = {
  'herbal-black-salt': 'Herbal Black Salt',
  'natural-lake-salt': 'Natural Lake Salt',
};

