export const getRecipe = (slug: string) => RECIPES.find((r) => r.slug === slug);

/** "10 min · Herbal Black Salt" */
export const recipeMeta = (r: Recipe) =>
  `${r.minutes} min · ${r.salts.map((s) => SALT_NAMES[s]).join(' + ')}`;
